  // ---- Heat: a temperature ramp (cool concrete, shown as itself -> warm -> hot) and a front that moves through the stack.
  // The stack's faces are filled by two gradients that run up the stack in the drawing's own projection; the hot zone
  // is at the top, where the hot fluid enters, grows downward on charge and is used up from the bottom on discharge.
  const rgb = (hex) => [1, 3, 5].map((at) => parseInt(hex.slice(at, at + 2), 16));
