  // `head` (0..1) draws the flow on along the routes in the order the plan lists them, which is the order the fluid takes.
  const flows = [...scope.querySelectorAll(".flow")].map((el) => ({ el, route: el.dataset.route, from: Number(el.dataset.from), span: Number(el.getAttribute("pathLength")) }));
