  function mount(scope, options = {}) {
  const FACTS = {"heaterMW":3,"capacityMWh":12,"maxTempC":390,"co2PerYear":700,"testedC":550,"cleanHeatGWh":3,"lineSharePct":70,"gasSavedGWh":3.5,"moduleMWh":2,"lossPct":2,"demandMW":0.4566,"breakeven":56.78};
  const HOURS = [{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0},{"p":0,"ed":0,"ec":0,"hd":0,"hs":0,"hb":0,"soc":0}];
  const SOC0 = 7.6036;
  const CH = {"w":720,"h":150,"l":38,"r":8,"t":12,"b":22};
  const CAP = FACTS.capacityMWh;
  const TEXT = JSON.parse(scope.querySelector(".tbx").dataset.strings); // the page's language: what the readout and the play button say
  const num = (value, digits) => (TEXT.lang === "de" ? value.toFixed(digits).replace(".", ",").replace("-", "−") : value.toFixed(digits));

  // What each line carries in a given hour: [fluid, direction along the route]
  const TOPS = ["top"], UPPER = [], LOWEST = ["link0"], COLDS = ["cold"];
  const all = (plan, routes, use) => { for (const route of routes) plan[route] = use; };
  function planFor(h) {
    const plan = {}, open = [];
    const heater = h.ed + h.ec > 0.001, charging = h.ec > 0.001, direct = h.hd > 0.001, discharging = h.hs > 0.001, gas = h.hb > 0.001;
    if (heater) { plan.power = ["power", 1]; plan.suction = ["cool", 1]; plan.heaterOut = ["hot", 1]; open.push("suction"); }
    // Hot oil goes down through the stack on charge and has cooled by the lowest link; on discharge the return oil comes up
    if (charging) { plan.hotRiser = ["hot", 1]; all(plan, TOPS, ["hot", -1]); all(plan, UPPER, ["hot", 1]); all(plan, LOWEST, ["cool", 1]); all(plan, COLDS, ["cool", 1]); plan.element = ["hot", 1]; open.push("hotRiser"); }
    if (discharging) { all(plan, COLDS, ["cool", -1]); all(plan, LOWEST, ["cool", -1]); all(plan, UPPER, ["hot", -1]); all(plan, TOPS, ["hot", 1]); plan.hotRiser = ["hot", -1]; plan.element = ["cool", -1]; open.push("hotRiser"); }
    if (direct || discharging) { plan.supply = ["hot", 1]; plan.through = ["hot", 1]; plan.return = ["cool", 1]; open.push("supply", "return"); }
    if (gas) { plan.boilerOut = ["hot", 1]; open.push("boiler"); }
    // Whoever makes the heat, it leaves along the outlet for the factory and the return comes back
    if (direct || discharging || gas) { plan.outlet = ["hot", 1]; plan.returnIn = ["cool", 1]; }
    return { plan, open, heater };
  }
  const PLANS = HOURS.map(planFor);
  // The machine without a day (state key "mode", for a film scene that shows how it works and names no date):
  // "power" (the cable is live and the heater warms), "charge" (heater to the line and into the stack), "discharge" (stack to the line).
  // Beside a mode, "boiler" (0..1) fires the plant's gas boiler: flame, a warm shell and hot oil from it to the outlet.
  // Whenever heat is delivered (heater, store or boiler) hot oil runs out along the outlet and the return comes back.
  const MODES = { idle: { plan: {}, open: [], heater: false }, power: { plan: { power: ["power", 1] }, open: [], heater: true }, charge: planFor({ ed: 1, ec: 1, hd: 1, hs: 0, hb: 0 }), discharge: planFor({ ed: 0, ec: 0, hd: 0, hs: 1, hb: 0 }) };

  // ---- State. Everything the drawing shows follows from these values.
  // time (hour of the day, 0..24); live 0..1 (the plant running: flows, lamps and heat; 0 while it is being put together);
  // phase (dash travel); clad 0..1; build (assembly, 0..1 or one value per stage); callouts ({ id: 0..1 }, stage layout);
  // camera ({ x, y, zoom }, stage layout). With "mode" set the day is left out: mode, share (store 0..1), flow (0..1) and
  // boiler (the gas boiler firing, 0..1) say it all. existing (0..1 or null): the tie-in panel, the gas boiler and its line on
  // their own, whatever "build" says (build 0, existing 1: the site before the plant was built); null: they follow "build".
  // hold (0 or 1, with "mode"): the factory is supplied without a break. The lines that carry heat to it and bring the return
  // back in both "charge" and "discharge" (supply, the outlet and the returns) stay at full flow whatever "flow" says, so a film
  // can fade the rest out and in again around a switch between the two without the outlet blinking.
  const DEFAULTS = { time: 0, live: 1, phase: 0, clad: 0, build: 1, existing: null, callouts: {}, camera: null, mode: null, share: 0, flow: 1, boiler: 0, hold: 0 };
  const HELD = ["supply", "through", "return", "outlet", "returnIn"];
  const beatsFor = function(stage
) {
return [["assembly", 7.2], ["callouts", stage ? 4.3 : 0], ["start", 1], ["day", stage ? 27 : 36], ["end", stage ? 5.5 : 1]];
};

  // Assembly: when each stage starts and how long it takes (plate, plinths, the modules one by one, heater and boiler,
  // pipes, pumps and valves, then the power cabinets and their cable). A module has landed before the next one starts.
  const BUILD = [[0,0.7],[0.6,0.7],[1.2,0.85],[2.1,0.85],[3.1,0.9],[4,1.9],[5.4,0.9],[6.1,1]];
  function story({ ramp, shown, shots, beats, staged }) {
    const stages = BUILD.map(([at, seconds]) => ramp("assembly", { at, for: seconds, ease: "outCubic" })); // the plate is there from the first frame: its ramp is not used
    const span = beats.day.to - beats.day.from, firstOn = PLANS.findIndex((plan) => plan.heater);
    // the feed is named in the hour the heater first runs
    const labels = { battery: shown("callouts", { at: 0.2, for: 3.9 }), heater: shown("callouts", { at: 1.1, for: 3.0 }), power: firstOn < 0 || !span ? () => 0 : shown("day", { at: (firstOn / 24) * span + 0.15, for: 2.4 }) };
    // The camera: wide while the plant is put together, for its labels and through the night; in to the heater and its cable as the power
    // comes on, then to the heat front in the stack; wide again for the evening and the end.
    const CAM = {"heater":{"x":966.2,"y":365.1,"zoom":1.4},"front":{"x":773.8,"y":303.7,"zoom":1.3},"line":{"x":1021.7,"y":417.9,"zoom":1.3},"boiler":{"x":1110.3,"y":443.2,"zoom":1.3},"boilerBody":{"x":1149.2,"y":492.4,"zoom":1}};
    const hour = (h) => (h / 24) * span;
    const camera = shots([
      ...(firstOn < 0 || !span ? [] : [
        { beat: "day", at: hour(firstOn) - 1.6, for: 2, to: CAM.heater },
        { beat: "day", at: hour(firstOn) + 2.9, for: 2, to: CAM.front }, // when the label of the cable has gone
        { beat: "day", at: hour(firstOn) + 5.6, for: 2.2, to: null },
      ]),
    ]);
    const live = ramp("start", { ease: "inOutQuad" }); // the day opens with the store as full as the night before left it
    const day = ramp("day");
    return (t, beat) => ({ beat, time: 24 * day.v, live: live.v, phase: 15 * Math.max(0, t - beats.day.from), build: stages.map((stage, index) => (index ? stage.v : 1)), callouts: { battery: labels.battery(), heater: labels.heater(), power: labels.power() }, camera: staged ? camera() : null });
  }

  const root = scope.querySelector(".tbx");
  const readout = root.closest(".iso-plate") && root.closest(".iso-plate").querySelector("[data-readout]");
  const playButton = root.querySelector("[data-play]");
  const slider = scope.querySelector(".day-chart input");
  const cursor = scope.querySelector("[data-cursor]");

  function draw(s, c) {
    if (s.mode) { // the machine, not a day
      const now = MODES[s.mode] || MODES.idle, flow = c.clamp(s.flow, 0, 1) * s.live, fire = c.clamp(s.boiler, 0, 1) * s.live;
      c.drawBuild(s.build, s.existing);
      c.drawHeat(c.clamp(s.share, 0, 1), s.live, (id) => (id === "heater" ? (now.heater ? flow * 0.5 : 0) : id === "boiler" ? fire * 0.3 : s.share));
      const held = s.hold && now.plan.supply ? s.live : flow; // the lines to the factory, when it is supplied without a break
      const kit = now.plan.supply ? held : 0; // heat from the heater or the store
      c.drawFlows(fire > 0 ? { ...now.plan, boilerOut: ["hot", 1], outlet: ["hot", 1], returnIn: ["cool", 1] } : now.plan, s.phase, (route) => (route === "boilerOut" ? fire : route === "outlet" || route === "returnIn" ? Math.max(kit, fire) : HELD.includes(route) ? held : flow));
      c.drawLamps((id) => (id === "boiler" ? fire : !now.open.includes(id) ? 0 : HELD.includes(id) ? held : flow));
      c.put(root, "data-heater", now.heater ? "1" : "0");
      c.drawClad(s.clad);
      c.drawCallouts(s.callouts);
      c.drawCamera(s.camera);
      return;
    }
    const time = c.clamp(s.time, 0, 24);
    const index = Math.min(23, Math.floor(time)), part = time - index;
    const h = HOURS[index], now = PLANS[index], before = PLANS[index - 1], after = PLANS[index + 1];
    const soc = (index ? HOURS[index - 1].soc : SOC0) + (h.soc - (index ? HOURS[index - 1].soc : SOC0)) * part;
    const share = soc / CAP;
    // A line, lamp or glow that changes at the hour fades out just before it and in just after, as a function of the time alone.
    const EDGE = 0.15;
    const fade = (is, was, will) => (is ? 1 : 0) * (before && !was ? c.smooth(part / EDGE) : 1) * (after && !will ? 1 - c.smooth((part - 1 + EDGE) / EDGE) : 1) * s.live;
    const same = (a, b) => Boolean(a && b) && a[0] === b[0] && a[1] === b[1];
    c.drawBuild(s.build, s.existing);
    const glow = fade(now.heater, before && before.heater, after && after.heater);
    const fire = fade(now.open.includes("boiler"), before && before.open.includes("boiler"), after && after.open.includes("boiler")); // the boiler's shell warms in an hour it fires
    c.drawHeat(share, s.live, (id) => (id === "heater" ? glow * 0.5 : id === "boiler" ? fire * 0.3 : share)); // the heater shell warms while it runs; Fig 2's element shows the store's mean
    c.drawFlows(now.plan, s.phase, (route) => fade(true, before && same(before.plan[route], now.plan[route]), after && same(after.plan[route], now.plan[route])));
    c.drawLamps((id) => fade(now.open.includes(id), before && before.open.includes(id), after && after.open.includes(id)));
    c.put(root, "data-heater", now.heater ? "1" : "0");
    c.drawClad(s.clad);
    c.drawCallouts(s.callouts);
    c.drawCamera(s.camera);
    const x = (CH.l + (time / 24) * (CH.w - CH.l - CH.r)).toFixed(1);
    c.put(cursor, "x1", x);
    c.put(cursor, "x2", x);
    if (slider && (document.activeElement !== slider || fig.playing)) slider.value = time.toFixed(2);
    const clock = String(Math.floor(time)).padStart(2, "0") + ":" + String(Math.floor(part * 60) % 60).padStart(2, "0");
    const text = TEXT.readout.replace("{clock}", clock).replace("{price}", num(h.p, 0)).replace("{heater}", num(h.ed + h.ec, 1)).replace("{store}", num(soc, 1)) + (h.hb > 0.001 ? TEXT.readoutGas.replace("{gas}", num(h.hb, 1)) : "");
    c.put(readout, "text", s.live > 0 ? text : "00:00"); // nothing to read out while the plant is still being put together
    c.put(slider, "aria-valuetext", text);
  }

  // ---- Driver: what the page does on its own clock. Playing is the story's day in a loop; the slider seeks; the dashes keep moving while paused.
  const still = matchMedia("(prefers-reduced-motion: reduce)");
  let cladWant = 0, cladNow = 0, drift = 0;
  function step(dt, playing) {
    cladNow += (cladWant - cladNow) * (1 - Math.exp(-dt / 0.14));
    if (Math.abs(cladWant - cladNow) < 0.005) cladNow = cladWant;
    if (playing) { fig.seek(fig.time, { clad: cladNow }); return true; }
    drift += 15 * dt;
    show();
    return !still.matches || cladNow !== cladWant;
  }
  const core = figureCore(scope, options, { defaults: DEFAULTS, beats: beatsFor, story, draw, step });
  const fig = core.handle;
  const { on, clamp } = core;
  const day = fig.beats.day;
  const show = (t = fig.time) => fig.seek(t, { clad: cladNow, phase: 15 * Math.max(0, t - day.from) + drift });
  const storyTime = (hour) => day.from + (hour / 24) * (day.to - day.from);
  function setClad(shown) { cladWant = shown ? 1 : 0; core.hide(); core.run(); }
  function setPlaying(next) {
    if (playButton) { playButton.textContent = next ? TEXT.pause : TEXT.play; playButton.setAttribute("aria-pressed", String(next)); }
    next ? fig.play([day.from, day.to]) : fig.pause();
    core.run();
  }

  if (!core.external && !core.staged) {
    on(playButton, "click", () => setPlaying(!fig.playing));
    on(root.querySelector('[data-toggle="clad"]'), "click", () => setClad(!cladWant));
    on(slider, "input", () => { if (fig.playing) setPlaying(false); show(storyTime(clamp(Number(slider.value), 0, 23.999))); });
    on(document, "keydown", (event) => {
      if (event.target.closest && event.target.closest("textarea,[contenteditable],input:not([type=range])")) return;
      if (event.key === " " && event.target.tagName !== "BUTTON") { event.preventDefault(); setPlaying(!fig.playing); }
      if (event.key === "i" || event.key === "I") setClad(!cladWant);
      if (event.key === "Escape") core.unpin();
    });
  }

  // Four still states for static exports (export.mjs): fig.pose("empty" | "charging" | "full" | "discharging").
  // They are hours of the day, found in its data: half an hour before the heater starts (the store at its lowest), the middle
  // of the heater's run, half an hour after it stops (the store at its fullest), and four hours later.
  const runs = PLANS.map((plan, hour) => (plan.heater ? hour : -1)).filter((hour) => hour >= 0);
  const [firstRun, lastRun] = [runs[0] ?? 12, (runs[runs.length - 1] ?? 12) + 1];
  const POSES = {
    empty: [firstRun - 0.5, { battery: 1, heater: 1 }],
    charging: [(firstRun + lastRun) / 2 + 0.5, { power: 1 }],
    full: [Math.min(23.5, lastRun + 0.5), {}],
    discharging: [Math.min(23.5, lastRun + 4.5), {}],
  };
  fig.pose = (name) => fig.seek(storyTime(POSES[name][0]), { callouts: POSES[name][1], phase: 0 });
  fig.poses = Object.keys(POSES);

  // Deep link: ?t=13.5&clad=1 opens at that hour, paused. The card page only.
  const query = new URLSearchParams(core.external || core.staged ? "" : location.search);
  if (query.get("clad") === "1") cladWant = cladNow = 1;
  if (core.external) fig.set({}); // assembled, at the start of the day, until the host seeks
  else if (core.staged) fig.seek(0).play([0, fig.duration]); // the stage page on its own just plays the film
  else if (query.has("t") || still.matches) { show(storyTime(query.has("t") ? clamp(Number(query.get("t")) || 0, 0, 23.999) : 13.5)); setPlaying(false); }
  else { fig.seek(0); setPlaying(true); } // assemble once, then the day in a loop
  return fig;
  }
  
export { mount };
